-- See https://wiki.hypr.land/configuring/core/autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
  -- First: after the automatic login at boot this shows the lock screen (which
  -- is the login screen) and waits for the first unlock; then it starts the
  -- programs in ~/.local/bin/session-apps (top bar, notifications, LocalSend,
  -- clipse, udiskie, ...). After a password login it starts them right away.
  hl.exec_cmd("~/.local/bin/session-start")

  -- Needed right away, also behind the lock screen
  hl.exec_cmd("~/.local/bin/monitor-maxrr --watch")  -- highest refresh rate at native resolution, also after hotplug
  hl.exec_cmd("fcitx5 -d --replace")
  hl.exec_cmd("swayosd-server")   -- volume/brightness popups (keys work on the lock screen)
  hl.exec_cmd("hypridle")         -- lock after 10 min idle (~/.config/hypr/hypridle.conf)
  hl.exec_cmd("awww-daemon")       -- wallpaper renderer
  hl.exec_cmd("~/.local/bin/wallpaper-restore")  -- last wallpaper (same as the login screen), then wallpaper-slideshow (first change after one interval)
end)

-- Switch fcitx5 to English whenever a terminal (or yazi, which runs in its own kitty window) gets focus
local terminalClasses = { kitty = true, yazi = true }
hl.on("window.active", function (window)
  if window and terminalClasses[window.class] then
    hl.dispatch(hl.dsp.exec_cmd("sleep 0.05; fcitx5-remote -c"))
  end
end)

-- 2026-11-24 master: rofi (launcher/menus) always opens with the English keyboard.
-- rofi is a layer surface, not a window, so window.active never fires for it; use layer.opened.
hl.on("layer.opened", function (layer)
  if layer and layer.namespace == "rofi" then
    hl.dispatch(hl.dsp.exec_cmd("fcitx5-remote -c"))
  end
end)


